function renderLibrary(){
if(gameKind==='tower'){renderTowerLibrary();return;}
const variant=gameKind==='tower'?'tower':'custom';if($('characterLibrary').dataset.kind!==variant){$('characterLibrary').innerHTML='';$('characterLibrary').dataset.kind=variant;}
if(!$('characterLibrary').innerHTML)$('characterLibrary').innerHTML=TYPES.map((t,i)=>`<button class="deployment-card" data-character="${i}" aria-pressed="false" aria-label="${t.name} 선택 · 임시 비용 ${t.cost}G · 다시 누르면 정보" style="--color:${t.color}"><b>${t.name}</b>${portrait(i)}<span>${t.cost}<small> G</small></span></button>`).join('');
for(const button of document.querySelectorAll('[data-character]')){const selected=+button.dataset.character===selectedCharacter&&placementTool==='character';button.classList.toggle('selected',selected);button.setAttribute('aria-pressed',selected);}
}
function openCharacterInfo(type,instance=null){const t=TYPES[type];if(!t)return;const enemy=instance?.towerEnemy?instance:null,member=instance?.guildId?towerMember(instance.guildId):null,stats=enemy?towerEnemyStats(enemy):member?towerMemberStats(member):gameKind==='custom'&&instance?{...customEquipmentStats(instance),dmg:customEquipmentStats(instance).dmg*stanceAttackFactor({combatStance:instance.stance})}:null;$('characterInfoContent').innerHTML=`<div class="info-header">${member?towerMemberPortrait(member):portrait(type)}<div><h2>${member?towerMemberName(member):t.name}</h2><p>${t.cost}G · HP ${member?Math.ceil(member.hp)+' / '+stats.hp:stats?.hp??t.hp} · ${stats?'ATK '+stats.dmg.toFixed(1):t.damageLabel??'ATK '+t.dmg} · 방어력 ${Math.round(stats?.defensePower??t.defensePower)}</p></div></div>${member?'<p class="tower-enemy-info guild-info">Lv.'+member.level+' · 기력 '+member.energy+' / 5 · 궁극기 '+Math.floor(member.ultGauge)+'%<br>상태: '+(towerStatusLabels(member).join(' · ')||'없음')+'<br>장비 '+towerEquippedCopies(member.id).length+'/'+towerEquipmentLimit(member)+': '+(towerEquippedItems(member.id).map(item=>item.name).join(' · ')||'없음')+'</p>':''}${enemy?'<p class="tower-enemy-info">'+(enemy.towerBoss?'강화 보스':enemy.towerElite?'강화 정예':'던전 적')+' · Lv.'+towerEnemyLevel(enemy)+' · 크기 '+Math.round(stats.scale*100)+'% · 공격력 '+stats.dmg.toFixed(1)+' · 이동속도 '+Math.round(stats.speed)+'</p>':''}<dl><dt>어그로 우선순위</dt><dd>${aggroPriorityHelp(type)}</dd><dt>행동 유형</dt><dd>${t.tags.map(tag=>`<b>[${tag}]</b> ${BEHAVIOR_HELP[tag]??'고유 전투 성향'}<br>`).join('')}</dd><dt>패시브 · ${t.passive}</dt><dd>${t.passiveHelp}</dd><dt>${type===8?'승부 판정':'치명타 · '+Math.round(t.critChance*100)+'%'}</dt><dd>${type===8?'가위바위보는 치명타·방어력의 영향을 받지 않습니다.':'치명타 적중 시 피해 1.5배.'}</dd>${t.attackHelp?'<dt>기본 공격</dt><dd>'+t.attackHelp+'</dd>':''}${ULTIMATES[type]?'<dt>궁극기 · '+ULTIMATES[type].name+'</dt><dd>'+ULTIMATES[type].help+'</dd>':'<dt>궁극기</dt><dd>없음.</dd>'}<dt>초월 스킬 · 검격</dt><dd>방향을 지정해 강한 참격. 아군만 사용 가능.</dd><dt>공통 수비 · 기본 패링</dt><dd>${BASIC_PARRY_HELP}</dd>${t.defense==='기본'?'':'<dt>고유 수비 · '+t.defense+'</dt><dd>'+t.defenseHelp+'</dd>'}</dl>`;$('characterInfo').showModal()}
$('closeCharacterInfo').onclick=()=>$('characterInfo').close();
function validPlacement(p){const min=p.towerEnemy?28:40,max=p.towerEnemy?772:760;return Number.isFinite(p.x)&&Number.isFinite(p.y)&&p.x>=min&&p.x<=max&&p.y>=min&&p.y<=max;}
function findPlacement(){for(let row=0;row<8;row++)for(let col=0;col<8;col++){const point={x:85+col*90,y:85+row*90};if(roster.every(p=>!validPlacement(p)||dist(p,point)>=58))return point;}return null;}
function ensureRosterPositions(){for(const p of roster)if(!validPlacement(p)){const point=findPlacement();if(point)Object.assign(p,point);}}
function teamSpending(team){return roster.filter(p=>p.team===team).reduce((sum,p)=>sum+TYPES[p.type].cost,0);}
function renderPlacementTeams(){if(!$('placementTeams').innerHTML)$('placementTeams').innerHTML=PLACEMENT_TEAM_ORDER.map((team,i)=>`<button data-placement-team="${team}" aria-pressed="false" class="placement-team" style="--team:${team<0?'#c0cbc5':TEAM_COLORS[team]}"><small>${i+1}</small> ${team<0?'개인':TEAM_NAMES[team]}</button>`).join('');for(const button of document.querySelectorAll('[data-placement-team]')){const selected=+button.dataset.placementTeam===selectedTeam;button.setAttribute('aria-pressed',selected);button.classList.toggle('active',selected);}}
function renderRoster(){
ensureRosterPositions();
$('placedUnits').innerHTML=roster.map(p=>`<button class="placed-unit ${p.towerElite?'tower-elite':''}" data-unit="${p.id}" ${!p.towerEnemy?'data-movable="true"':''} style="left:${p.x/8}%;top:${p.y/8}%;width:${6.75*(p.towerBodyScale??1)}%;--unit-scale:${p.towerBodyScale??1};--unit:${p.team<0?TYPES[p.type].color:TEAM_COLORS[p.team]}" aria-label="${p.towerBoss?'강화 보스 · ':p.towerElite?'정예 · ':''}${TYPES[p.type].name} · ${p.team<0?'개인':TEAM_NAMES[p.team]+' 팀'} · ${p.towerEnemy?'캐릭터 정보':'끌어 위치 이동 · 터치로 전투 성향'}"><span aria-hidden="true">${EMOJIS[p.type]}</span>${p.towerAlly&&towerMemberStars(towerMember(p.guildId))?'<small aria-label="성급">'+'⭐️'.repeat(towerMemberStars(towerMember(p.guildId)))+'</small>':''}${p.towerAlly?'<i class="placed-hp"><em style="width:'+clamp(towerMember(p.guildId).hp/towerMemberStats(towerMember(p.guildId)).hp*100,0,100)+'%"></em></i>':''}</button>`).join('');
$('teamCosts').innerHTML=PLACEMENT_TEAM_ORDER.map(team=>`<div style="--team:${team<0?'#c0cbc5':TEAM_COLORS[team]}"><span>${team<0?'개인':TEAM_NAMES[team]}</span><b>${teamSpending(team).toLocaleString('ko-KR')}<small> G</small></b></div>`).join('');
$('clearRoster').disabled=!roster.length;
$('configSummary').textContent=`${roster.length} / ${MAX_PARTICIPANTS}명 · ${new Set(roster.map(faction)).size}개 진영`;
$('deploymentMap').dataset.tool=placementTool;
$('eraser').setAttribute('aria-pressed',placementTool==='eraser');
$('validation').textContent=placementTool==='eraser'?'지울 유닛을 누르세요.':selectedCharacter===null?'카드를 선택하고 맵에 배치하세요.':`${TYPES[selectedCharacter].name} · ${selectedTeam<0?'개인':TEAM_NAMES[selectedTeam]+' 팀'} 배치 · 다시 누르면 정보`;
renderPlacementTeams();renderLibrary();if(gameKind==='tower')decorateTowerDeployment();else{
$('budgetCaption').hidden=false;$('teamCosts').classList.remove('tower-wallet');$('deploymentBudget').classList.remove('tower-resource-budget');$('teamCosts').setAttribute('aria-label','팀별 사용 비용');$('setupTitle').textContent='전투 설정';$('budgetTitle').textContent='팀별 사용 비용';$('budgetFunds').textContent='자금 ∞';$('placementTeams').hidden=false;$('towerDeployHint').hidden=true;$('deploymentMap').classList.remove('tower-map');$('openSetupSettings').textContent='⚙ 설정';$('backHome').textContent='메인으로';$('backHome').hidden=false;
}
}
function addParticipant(type,{team=selectedTeam,x,y}={}){
if(gameKind==='tower')return addTowerParticipant(type,{x,y});
if(!Number.isInteger(type)||!TYPES[type])throw Error('존재하지 않는 캐릭터입니다.');
if(roster.length>=MAX_PARTICIPANTS){$('validation').textContent='한 전투에 최대 24명까지 참전할 수 있습니다.';return false;}
if(!PLACEMENT_TEAM_ORDER.includes(team))return false;
ensureRosterPositions();const point=Number.isFinite(x)&&Number.isFinite(y)?{x:clamp(x,40,760),y:clamp(y,40,760)}:findPlacement();
if(!point||roster.some(p=>dist(p,point)<58)){$('validation').textContent='유닛끼리 겹치지 않도록 조금 떨어진 곳에 배치하세요.';return false;}
roster.push({id:nextId++,type,team,...point});$('validation').textContent='';renderRoster();return true;
}
function selectPlacementCharacter(type){if(!TYPES[type])return;if(selectedCharacter===type&&placementTool==='character'){openCharacterInfo(type);return;}selectedCharacter=type;placementTool='character';renderRoster();}
function placeSelected(point){if(placementTool==='eraser')return;if(gameKind==='tower'){addTowerParticipant(towerPlacementUnitId,point);return;}if(selectedCharacter===null){$('validation').textContent='먼저 하단에서 캐릭터 카드를 선택하세요.';return;}addParticipant(selectedCharacter,{team:selectedTeam,...point});}
let placementDrag=null,suppressPlacementClickUntil=0;
function placementUnitMovable(p){return !!p&&['setup','towerSetup'].includes(screen)&&placementTool!=='eraser'&&(gameKind!=='tower'||tower?.phase==='deploy'&&p.towerAlly);}
function placementMovePoint(point){return{x:clamp(point.x,40,gameKind==='tower'?380:760),y:clamp(point.y,40,760)};}
function placementMoveError(p,point){if(!placementUnitMovable(p)||!Number.isFinite(point.x)||!Number.isFinite(point.y))return '이 유닛은 옮길 수 없습니다.';if(roster.some(u=>u.id!==p.id&&dist(u,point)<58))return '유닛과 조금 떨어진 곳으로 옮기세요.';return '';}
function movePlacedParticipant(id,point,redraw=true){const p=roster.find(u=>u.id===id),next=placementMovePoint(point),error=placementMoveError(p,next);if(error){$('validation').textContent=error;return false;}Object.assign(p,next);if(redraw)renderRoster();else $('validation').textContent='';return true;}
function placementPointerPoint(e){const r=$('deploymentMap').getBoundingClientRect();return{x:(e.clientX-r.left)/r.width*800,y:(e.clientY-r.top)/r.height*800};}
$('deploymentMap').addEventListener('pointerdown',()=>{suppressPlacementClickUntil=0;},true);
$('deploymentMap').addEventListener('click',e=>{if(e.detail!==0&&Date.now()<suppressPlacementClickUntil){suppressPlacementClickUntil=0;e.preventDefault();e.stopPropagation();}},true);
$('placedUnits').addEventListener('pointerdown',e=>{
 if(placementDrag||e.isPrimary===false||e.button!==0)return;const button=e.target.closest('[data-unit]'),p=roster.find(u=>u.id===+button?.dataset.unit);if(!placementUnitMovable(p))return;
 const point=placementPointerPoint(e);placementDrag={id:p.id,pointerId:e.pointerId,button,startX:e.clientX,startY:e.clientY,offsetX:point.x-p.x,offsetY:point.y-p.y,point:{x:p.x,y:p.y},moved:false};
});
window.addEventListener('pointermove',e=>{
 const drag=placementDrag;if(!drag||drag.pointerId!==e.pointerId)return;if(!drag.moved){if(Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)<6)return;drag.moved=true;drag.button.setPointerCapture(e.pointerId);}e.preventDefault();
 const point=placementPointerPoint(e);drag.point=placementMovePoint({x:point.x-drag.offsetX,y:point.y-drag.offsetY});drag.button.style.left=drag.point.x/8+'%';drag.button.style.top=drag.point.y/8+'%';drag.button.classList.add('dragging');drag.button.classList.toggle('drop-blocked',!!placementMoveError(roster.find(p=>p.id===drag.id),drag.point));
});
function finishPlacementDrag(e,cancel=false){
 const drag=placementDrag;if(!drag||drag.pointerId!==e.pointerId)return;placementDrag=null;if(drag.moved&&drag.button.hasPointerCapture(e.pointerId))drag.button.releasePointerCapture(e.pointerId);
 if(drag.moved){suppressPlacementClickUntil=cancel?0:Date.now()+400;if(!cancel)movePlacedParticipant(drag.id,drag.point,false);const p=roster.find(u=>u.id===drag.id);if(p){drag.button.style.left=p.x/8+'%';drag.button.style.top=p.y/8+'%';}drag.button.classList.remove('dragging','drop-blocked');}
 else if(!cancel&&e.pointerType==='touch'){suppressPlacementClickUntil=Date.now()+400;activatePlacedUnit(drag.id);}
}
window.addEventListener('pointerup',e=>finishPlacementDrag(e));
window.addEventListener('pointercancel',e=>finishPlacementDrag(e,true));
$('placedUnits').addEventListener('lostpointercapture',e=>{if(e.target===placementDrag?.button)finishPlacementDrag(e,true);});
$('placedUnits').addEventListener('keydown',e=>{const delta={ArrowLeft:[-20,0],ArrowRight:[20,0],ArrowUp:[0,-20],ArrowDown:[0,20]}[e.key],button=e.target.closest('[data-unit]'),p=roster.find(u=>u.id===+button?.dataset.unit);if(!delta||!placementUnitMovable(p))return;e.preventDefault();if(movePlacedParticipant(p.id,{x:p.x+delta[0],y:p.y+delta[1]}))$('placedUnits').querySelector(`[data-unit="${p.id}"]`)?.focus();});
$('characterLibrary').addEventListener('click',e=>{const guild=e.target.closest('[data-guild-unit]');if(guild){const scroll=$('characterLibrary').scrollLeft;selectTowerPlacementMember(+guild.dataset.guildUnit);$('characterLibrary').scrollLeft=scroll;return;}const card=e.target.closest('[data-character]');if(!card)return;const scroll=$('characterLibrary').scrollLeft;selectPlacementCharacter(+card.dataset.character);$('characterLibrary').scrollLeft=scroll;});
$('placementTeams').addEventListener('click',e=>{const button=e.target.closest('[data-placement-team]');if(!button)return;selectedTeam=+button.dataset.placementTeam;renderRoster();});
function activatePlacedUnit(id){const p=roster.find(p=>p.id===id);if(!p)return;if(placementTool==='eraser'){if(gameKind==='tower'){removeTowerParticipant(p.id);return;}roster=roster.filter(v=>v.id!==p.id);renderRoster();}else if(typeof openUnitStrategy==='function')openUnitStrategy(p.id);else openCharacterInfo(p.type);}
$('placedUnits').addEventListener('click',e=>{const button=e.target.closest('[data-unit]');if(button)activatePlacedUnit(+button.dataset.unit);});
$('placementSurface').addEventListener('click',e=>{const rect=$('deploymentMap').getBoundingClientRect();const point=e.detail===0?placementCursor:{x:(e.clientX-rect.left)/rect.width*800,y:(e.clientY-rect.top)/rect.height*800};placeSelected(point);});
$('placementSurface').addEventListener('keydown',e=>{const delta={ArrowLeft:[-40,0],ArrowRight:[40,0],ArrowUp:[0,-40],ArrowDown:[0,40]}[e.key];if(!delta)return;e.preventDefault();placementCursor.x=clamp(placementCursor.x+delta[0],40,760);placementCursor.y=clamp(placementCursor.y+delta[1],40,760);$('placementCursor').hidden=false;$('placementCursor').style.left=placementCursor.x/8+'%';$('placementCursor').style.top=placementCursor.y/8+'%';});
$('placementSurface').addEventListener('blur',()=>{$('placementCursor').hidden=true;});
