$('homeLogo').onclick=()=>showScreen('home');$('backHome').onclick=()=>showScreen('home');$('newBattle').onclick=()=>{showScreen('setup')};$('returnSetup').onclick=()=>{if(hasTowerPrediction()){returnTowerPrediction();return;}if(gameKind==='tower'){returnTowerFromBattle();return;}showScreen(gameKind==='prediction'?'prediction':'setup')};
window.addEventListener('popstate',()=>{if(towerHpGameOverActive()){history.replaceState?.(null,'','#battle');return;}let dest=location.hash.slice(1);if(towerCombatEntryLocked()){history.replaceState?.(null,'','#'+screen);towerCombatNavigationNotice();return;}if(towerEventInProgress()){history.replaceState?.(null,'','#'+screen);towerEventNavigationNotice();return;}if(hasTowerPrediction()){leaveTowerPrediction();showScreen('tower',false);history.replaceState?.(null,'','#tower');return;}if(dest==='battle'&&battleSnapshot?.towerPredictionRoomId){enterTower({push:false});history.replaceState?.(null,'','#tower');return;}if(gameKind==='tower'&&screen==='battle'&&running&&dest!=='battle'&&!canRetreatTower()){history.pushState(null,'','#battle');return;}if(gameKind==='tower'&&!['tower','towerSetup'].includes(dest)&&(dest!=='battle'||battleSnapshot?.kind!=='tower')){if(screen==='battle'&&running&&!retreatTowerBattle({navigate:false})){history.pushState(null,'','#battle');return;}leaveTowerMode();gameKind='custom';}if(['tower','towerSetup'].includes(dest)){enterTower({push:false});return;}if(dest==='battle'&&battleSnapshot?.kind==='tower'){enterTower({push:false});return;}if(dest==='battle'&&battleSnapshot){gameKind=battleSnapshot.kind;predictionPick=battleSnapshot.pick;if(gameKind==='prediction'&&!customRoster)customRoster=roster.map(p=>({...p}));roster=battleSnapshot.roster.map(p=>({...p}));}if(dest==='prediction'&&!predictionTeams.length){generatePrediction();return;}showScreen(dest==='battle'&&!units.length?'setup':['home','setup','prediction','battle'].includes(dest)?dest:'home',false);if(dest==='battle'&&units.length&&!running&&!finished){paused=true;running=true;$('pause').disabled=false;setPauseLabel()}});
